CREATE TRIGGER trgNoDrop ON DATABASE FOR DROP_TABLE AS
  PRINT 'Tables cannot be dropped';
  ROLLBACK;

DECLARE c CURSOR FOR SELECT Id FROM dbo.Queue;
OPEN c;
FETCH NEXT FROM c INTO @id;
WHILE @@FETCH_STATUS = 0
  FETCH NEXT FROM c INTO @id;
CLOSE c;
DEALLOCATE c;

DISABLE TRIGGER trgAudit ON dbo.Products;
-- maintenance
ENABLE TRIGGER trgAudit ON dbo.Products;

CREATE TRIGGER trgPrice ON dbo.Products AFTER UPDATE AS
  UPDATE p SET ModifiedAt = SYSUTCDATETIME()
  FROM dbo.Products p JOIN inserted i ON i.Id = p.Id;
